YPE-II-AFCI-WIFI-LAN/1755101"},{"supplier_sku":"1763663","brand":"SolaX Power","category":"Střídače","name":"XHub","source_url":"https://shop.krannich-solar.com/cs-cz/XHub/1763663"}]$solax_rows$::jsonb) as x(
    supplier_sku text,
    brand text,
    category text,
    name text,
    source_url text
  )
), krannich as (
  select id from public.product_suppliers where slug = 'krannich-solar'
), updated_offers as (
  update public.product_supplier_offers offer
  set metadata = coalesce(offer.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'brand', source_rows.brand,
        'manufacturer', source_rows.brand,
        'supplier_category', source_rows.category,
        'brand_backfill_source', 'krannich_products_20260704_portal_import.csv'
      ),
      supplier_category = coalesce(nullif(offer.supplier_category, ''), source_rows.category),
      supplier_product_url = coalesce(offer.supplier_product_url, source_rows.source_url),
      updated_at = now()
  from source_rows, krannich
  where offer.supplier_id = krannich.id
    and lower(offer.supplier_sku) = lower(source_rows.supplier_sku)
  returning offer.catalog_item_id
), updated_catalog as (
  update public.commercial_item_catalog item
  set metadata = coalesce(item.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'brand', source_rows.brand,
        'manufacturer', source_rows.brand,
        'supplier_category', coalesce(item.metadata->>'supplier_category', source_rows.category),
        'brand_backfill_source', 'krannich_products_20260704_portal_import.csv'
      ),
      category = coalesce(nullif(item.category, ''), source_rows.category),
      updated_at = now()
  from source_rows
  where lower(item.sku) = lower(source_rows.supplier_sku)
     or lower(item.code) = lower(source_rows.supplier_sku)
  returning item.id
)
select
  (select count(*) from source_rows) as input_rows,
  (select count(*) from updated_offers) as updated_offers,
  (select count(*) from updated_catalog) as updated_catalog;

commit;
